// driveConfigDir returns (and creates) ~/Library/Application Support/paper-scan-processor.
func driveConfigDir() (string, error) {
	base, err := os.UserConfigDir()
	if err != nil {
		return "", err
	}
	dir := filepath.Join(base, "paper-scan-processor")
